import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`airbnb-listing`,heroTitle:`Optimize your Airbnb listing in minutes`,heroSubtitle:`Perplexity Computer benchmarks your listing, rewrites your copy, and builds a seasonal rate calendar automatically.`,inputUrlCta:`Optimize my listing`,inputUrlPlaceholder:`e.g. airbnb.com/rooms...`,inputUrlPrefill:`Go to {url} and do a full analysis of this Airbnb listing. 1) Benchmark it against the top 10 performing listings in the same area by comparing titles, descriptions, photos, amenities, and pricing. 2) Rewrite the listing title and description to maximize bookings based on what top performers do well. 3) Analyze local pricing trends and suggest an optimized nightly rate. 4) Build a 12-month seasonal rate calendar with recommended prices for peak, shoulder, and off-peak periods. 5) List specific improvements for photos, amenities, and guest experience based on competitor gaps.`,heroOverlaySteps:[`Pulling your listing details — title, description, photos, amenities, and current pricing`,`Benchmarking against the top 10 listings in your area by revenue and reviews`,`Rewriting your copy and modeling optimal nightly rates by season`,`Competitive analysis, optimized copy, and 12-month rate calendar — ready to publish`],generatingSteps:[`Visiting {url} to extract your listing details, pricing, and local market`,`Designing an agent to benchmark your listing against top performers in your area`,`Configuring copy optimization and seasonal pricing models for your market`,`Setting up a 12-month rate calendar and competitive improvement roadmap`],featureSectionTitle:`From listing to top performer`,featureCardTitles:[`Connects to your hosting stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Notion, Outlook — Computer connects to the tools you already use so insights flow straight into your workflow.`,`Rewritten listing copy. Competitive benchmark report. Seasonal rate calendar. Amenity gap analysis. Computer delivers work you can paste into Airbnb today.`],capabilitySectionTitle:`Your hosting manager, on autopilot`,capabilitySectionSubtitle:`Paste your listing, step away, come back to a revenue-optimized strategy.`,capabilityCards:[{title:`Market Benchmarking`,description:`Computer can analyze the top-performing listings in your area — occupancy, pricing, reviews, amenities — and show exactly where you stand.`},{title:`Copy Optimization`,description:`Computer can rewrite your title, description, and amenity highlights based on what converts best in your market — tuned for Airbnb search.`},{title:`Pricing Strategy`,description:`Computer can model local demand patterns and build a 12-month seasonal rate calendar with peak, shoulder, and off-peak pricing recommendations.`},{title:`Connect Your Tools`,description:`Computer can read and write to Airbnb, PriceLabs, Google Sheets, Notion, and more — build workflows across your entire hosting stack.`},{title:`Remember & Learn`,description:`Computer can remember your property details, guest personas, and pricing history across sessions — so every optimization builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch competitor pricing and local demand shifts — set up a monitoring workflow that pings you when it’s time to adjust rates.`}]});export{t as default};
